select '270c3094-7df5-56ad-b20c-2447b2593e0c', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Santiago''s new hobby","text":"Santiago is sixteen and lives in a small town near Manizales. Last year his uncle gave him an old pair of binoculars for his birthday. At first, Santiago didn''t know what to do with them. Then one morning he saw a bright green bird in the garden and wanted to know its name. He looked for it in a book at the town library and found out it was a parrot that lives only in the Andes.\n\nNow Santiago gets up at five every Saturday and walks to the forest with two friends from school. They write down every bird they see in a notebook and take photos with a mobile phone. So far they have seen more than ninety different species. Santiago says the hardest part is being quiet for a long time. Next year he wants to study biology at university.","svg":null,"table":null}'::jsonb, 'How did Santiago get his binoculars?', '[{"label":"A","text":"He bought them at the library.","is_correct":false,"distractor_type":"Mezcla dos datos del texto (binoculares y biblioteca).","explanation_feedback":"Incorrecta. En la biblioteca buscó el nombre del pájaro; no compró nada allí."},{"label":"B","text":"A friend from school lent them.","is_correct":false,"distractor_type":"Asocia a los amigos del colegio con los binoculares.","explanation_feedback":"Incorrecta. Los amigos lo acompañan al bosque, pero los binoculares fueron de su tío."},{"label":"C","text":"He found them in the garden.","is_correct":false,"distractor_type":"Relaciona «garden» con los binoculares.","explanation_feedback":"Incorrecta. En el jardín vio el pájaro verde, no encontró los binoculares."},{"label":"D","text":"They were a present from his uncle.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que su tío se los regaló de cumpleaños («his uncle gave him… for his birthday»)."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
