select '39bb1e66-ace2-55b9-8c79-241415c7c1be', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Santiago''s new hobby","text":"Santiago is sixteen and lives in a small town near Manizales. Last year his uncle gave him an old pair of binoculars for his birthday. At first, Santiago didn''t know what to do with them. Then one morning he saw a bright green bird in the garden and wanted to know its name. He looked for it in a book at the town library and found out it was a parrot that lives only in the Andes.\n\nNow Santiago gets up at five every Saturday and walks to the forest with two friends from school. They write down every bird they see in a notebook and take photos with a mobile phone. So far they have seen more than ninety different species. Santiago says the hardest part is being quiet for a long time. Next year he wants to study biology at university.","svg":null,"table":null}'::jsonb, 'What made Santiago start using the binoculars?', '[{"label":"A","text":"He wanted to know the name of a bird.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al ver un pájaro verde en el jardín quiso saber su nombre, y así empezó."},{"label":"B","text":"His friends asked him to go to the forest.","is_correct":false,"distractor_type":"Invierte el orden de los hechos.","explanation_feedback":"Incorrecta. Las salidas con sus amigos vinieron después de descubrir el pájaro."},{"label":"C","text":"He had a biology project at school.","is_correct":false,"distractor_type":"Relaciona biología con una tarea escolar.","explanation_feedback":"Incorrecta. La biología aparece como plan futuro, no como motivo inicial."},{"label":"D","text":"His uncle taught him how to use them.","is_correct":false,"distractor_type":"Supone una información que el texto no da.","explanation_feedback":"Incorrecta. El texto no dice que el tío le enseñara a usarlos."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
