select '01527aad-fbcb-546e-9df1-7a028bb6c421', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Santiago''s new hobby","text":"Santiago is sixteen and lives in a small town near Manizales. Last year his uncle gave him an old pair of binoculars for his birthday. At first, Santiago didn''t know what to do with them. Then one morning he saw a bright green bird in the garden and wanted to know its name. He looked for it in a book at the town library and found out it was a parrot that lives only in the Andes.\n\nNow Santiago gets up at five every Saturday and walks to the forest with two friends from school. They write down every bird they see in a notebook and take photos with a mobile phone. So far they have seen more than ninety different species. Santiago says the hardest part is being quiet for a long time. Next year he wants to study biology at university.","svg":null,"table":null}'::jsonb, 'What do Santiago and his friends do every Saturday?', '[{"label":"A","text":"They help his uncle in the garden.","is_correct":false,"distractor_type":"Mezcla personajes y lugares del texto.","explanation_feedback":"Incorrecta. El texto no dice que ayuden al tío en el jardín."},{"label":"B","text":"They visit the library to read about birds.","is_correct":false,"distractor_type":"Toma una acción que hizo una sola vez.","explanation_feedback":"Incorrecta. Fue a la biblioteca una vez para buscar el nombre del loro, no cada sábado."},{"label":"C","text":"They record the birds they see in the forest.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Caminan al bosque, anotan cada pájaro en un cuaderno y toman fotos."},{"label":"D","text":"They sell photos of birds to tourists.","is_correct":false,"distractor_type":"Agrega información que no está en el texto.","explanation_feedback":"Incorrecta. El texto no menciona turistas ni ventas."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
