select '9a56e352-b231-55d6-b915-cd540b681d72', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Santiago''s new hobby","text":"Santiago is sixteen and lives in a small town near Manizales. Last year his uncle gave him an old pair of binoculars for his birthday. At first, Santiago didn''t know what to do with them. Then one morning he saw a bright green bird in the garden and wanted to know its name. He looked for it in a book at the town library and found out it was a parrot that lives only in the Andes.\n\nNow Santiago gets up at five every Saturday and walks to the forest with two friends from school. They write down every bird they see in a notebook and take photos with a mobile phone. So far they have seen more than ninety different species. Santiago says the hardest part is being quiet for a long time. Next year he wants to study biology at university.","svg":null,"table":null}'::jsonb, 'According to Santiago, what is the most difficult thing about his hobby?', '[{"label":"A","text":"Staying silent for a long time.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Él dice que lo más difícil es «being quiet for a long time»."},{"label":"B","text":"Walking a long way to the forest.","is_correct":false,"distractor_type":"Supone una dificultad que el texto no menciona.","explanation_feedback":"Incorrecta. El texto no dice que el camino sea largo ni difícil."},{"label":"C","text":"Getting up at five in the morning.","is_correct":false,"distractor_type":"Elige un dato del texto que parece difícil, pero no es el que él señala.","explanation_feedback":"Incorrecta. Se levanta a las cinco, pero no dice que eso sea lo más difícil."},{"label":"D","text":"Taking good photos with a phone.","is_correct":false,"distractor_type":"Relaciona la cámara del celular con una dificultad.","explanation_feedback":"Incorrecta. Toman fotos con el celular, pero no dice que sea lo más difícil."}]'::js