select 'acdb3015-360c-5702-8e71-ae6b86ec3c20', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Santiago''s new hobby","text":"Santiago is sixteen and lives in a small town near Manizales. Last year his uncle gave him an old pair of binoculars for his birthday. At first, Santiago didn''t know what to do with them. Then one morning he saw a bright green bird in the garden and wanted to know its name. He looked for it in a book at the town library and found out it was a parrot that lives only in the Andes.\n\nNow Santiago gets up at five every Saturday and walks to the forest with two friends from school. They write down every bird they see in a notebook and take photos with a mobile phone. So far they have seen more than ninety different species. Santiago says the hardest part is being quiet for a long time. Next year he wants to study biology at university.","svg":null,"table":null}'::jsonb, 'What is the text mainly about?', '[{"label":"A","text":"How to choose a good pair of binoculars.","is_correct":false,"distractor_type":"Infiere un propósito instructivo que no tiene el texto.","explanation_feedback":"Incorrecta. El texto narra una experiencia; no da consejos para comprar binoculares."},{"label":"B","text":"Why parrots only live in the Andes.","is_correct":false,"distractor_type":"Toma un detalle por la idea principal.","explanation_feedback":"Incorrecta. El loro de los Andes es solo un detalle del relato."},{"label":"C","text":"What students study in biology courses.","is_correct":false,"distractor_type":"Toma el plan futuro como tema central.","explanation_feedback":"Incorrecta. La biología aparece solo al final, como un plan."},{"label":"D","text":"How a gift led a teenager to a new interest.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto cuenta cómo unos binoculares regalados llevaron a Santiago a observar aves."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
