select '549bfa16-28ae-5307-9f4a-d0d4758cc8e1', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"The school garden","text":"Two years ago, the students at Colegio La Esperanza had an idea. Behind the school there was a piece of land full of rubbish. The students asked the head teacher if they could clean it and use it to grow vegetables. She agreed, but only if they promised to look after it during the holidays too.\n\nToday the garden has tomatoes, lettuce, beans and herbs. Each class is responsible for one part of the garden for a month. The vegetables are used in the school kitchen, and the students eat them at lunch. Last month they grew so many tomatoes that they sold some to families in the neighbourhood and used the money to buy new tools.\n\nThe science teacher, Mr Rojas, also uses the garden for his classes. \"It''s easier to understand how plants grow when you see it with your own eyes,\" he says.","svg":null,"table":null}'::jsonb, 'What was behind the school before the garden?', '[{"label":"A","text":"A football field for students.","is_correct":false,"distractor_type":"Supone un uso escolar común.","explanation_feedback":"Incorrecta. No era una cancha: era un terreno con basura."},{"label":"B","text":"A small farm with animals.","is_correct":false,"distractor_type":"Imagina un uso anterior que el texto no menciona.","explanation_feedback":"Incorrecta. El texto no habla de una granja ni de animales."},{"label":"C","text":"A piece of land with a lot of rubbish.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que era un terreno «full of rubbish» (lleno de basura)."},{"label":"D","text":"An old school kitchen.","is_correct":false,"distractor_type":"Confunde la cocina actual con el terreno.","explanation_feedback":"Incorrecta. La cocina se menciona como destino de las verduras, no como lo que había detrás."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
