select 'afcdb013-b1e3-57da-b27d-9e069b4c179e', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"The school garden","text":"Two years ago, the students at Colegio La Esperanza had an idea. Behind the school there was a piece of land full of rubbish. The students asked the head teacher if they could clean it and use it to grow vegetables. She agreed, but only if they promised to look after it during the holidays too.\n\nToday the garden has tomatoes, lettuce, beans and herbs. Each class is responsible for one part of the garden for a month. The vegetables are used in the school kitchen, and the students eat them at lunch. Last month they grew so many tomatoes that they sold some to families in the neighbourhood and used the money to buy new tools.\n\nThe science teacher, Mr Rojas, also uses the garden for his classes. \"It''s easier to understand how plants grow when you see it with your own eyes,\" he says.","svg":null,"table":null}'::jsonb, 'What condition did the head teacher give the students?', '[{"label":"A","text":"They had to care for the garden in the holidays.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella aceptó solo si prometían cuidarlo también en vacaciones."},{"label":"B","text":"They had to get help from Mr Rojas.","is_correct":false,"distractor_type":"Relaciona al profesor con la condición.","explanation_feedback":"Incorrecta. El profesor usa el huerto en sus clases, pero no fue la condición."},{"label":"C","text":"They had to pay for the vegetables.","is_correct":false,"distractor_type":"Inventa una condición económica.","explanation_feedback":"Incorrecta. El texto no dice que tuvieran que pagar nada."},{"label":"D","text":"They had to give the tomatoes to families.","is_correct":false,"distractor_type":"Toma un hecho posterior como condición.","explanation_feedback":"Incorrecta. La venta a las familias ocurrió después y no fue una condición."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
