select '9ec49988-9290-51e5-af43-06baecc48377', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"The school garden","text":"Two years ago, the students at Colegio La Esperanza had an idea. Behind the school there was a piece of land full of rubbish. The students asked the head teacher if they could clean it and use it to grow vegetables. She agreed, but only if they promised to look after it during the holidays too.\n\nToday the garden has tomatoes, lettuce, beans and herbs. Each class is responsible for one part of the garden for a month. The vegetables are used in the school kitchen, and the students eat them at lunch. Last month they grew so many tomatoes that they sold some to families in the neighbourhood and used the money to buy new tools.\n\nThe science teacher, Mr Rojas, also uses the garden for his classes. \"It''s easier to understand how plants grow when you see it with your own eyes,\" he says.","svg":null,"table":null}'::jsonb, 'How is the work in the garden organised?', '[{"label":"A","text":"Only the science class can work there.","is_correct":false,"distractor_type":"Generaliza el uso del profesor de ciencias.","explanation_feedback":"Incorrecta. El profesor usa el huerto, pero todos los cursos participan."},{"label":"B","text":"The head teacher does most of the work.","is_correct":false,"distractor_type":"Supone que la rectora trabaja en el huerto.","explanation_feedback":"Incorrecta. El texto dice que los cursos se turnan; no habla de la rectora trabajando."},{"label":"C","text":"Families from the neighbourhood help every day.","is_correct":false,"distractor_type":"Confunde a los compradores con trabajadores.","explanation_feedback":"Incorrecta. Las familias compraron tomates; no trabajan en el huerto."},{"label":"D","text":"Each class looks after one area for a month.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada curso se encarga de una parte del huerto durante un mes."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
