select 'adbb7f6c-0777-56b1-8bf9-f77c64081527', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"The school garden","text":"Two years ago, the students at Colegio La Esperanza had an idea. Behind the school there was a piece of land full of rubbish. The students asked the head teacher if they could clean it and use it to grow vegetables. She agreed, but only if they promised to look after it during the holidays too.\n\nToday the garden has tomatoes, lettuce, beans and herbs. Each class is responsible for one part of the garden for a month. The vegetables are used in the school kitchen, and the students eat them at lunch. Last month they grew so many tomatoes that they sold some to families in the neighbourhood and used the money to buy new tools.\n\nThe science teacher, Mr Rojas, also uses the garden for his classes. \"It''s easier to understand how plants grow when you see it with your own eyes,\" he says.","svg":null,"table":null}'::jsonb, 'What did the students do with the extra tomatoes?', '[{"label":"A","text":"They sold them and bought new tools.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Vendieron tomates a familias del barrio y compraron herramientas nuevas."},{"label":"B","text":"They gave them to Mr Rojas.","is_correct":false,"distractor_type":"Relaciona al profesor con los tomates.","explanation_feedback":"Incorrecta. El texto no dice que se los dieran al profesor."},{"label":"C","text":"They took them home for the holidays.","is_correct":false,"distractor_type":"Relaciona «holidays» con los tomates.","explanation_feedback":"Incorrecta. Las vacaciones aparecen en la condición de la rectora, no en lo que hicieron con los tomates."},{"label":"D","text":"They threw them away with the rubbish.","is_correct":false,"distractor_type":"Relaciona «rubbish» con los tomates.","explanation_feedback":"Incorrecta. La basura era lo que había antes en el terreno."}]'::jsonb, 