select 'd3782d83-6743-506d-a130-a0df924b7262', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"The school garden","text":"Two years ago, the students at Colegio La Esperanza had an idea. Behind the school there was a piece of land full of rubbish. The students asked the head teacher if they could clean it and use it to grow vegetables. She agreed, but only if they promised to look after it during the holidays too.\n\nToday the garden has tomatoes, lettuce, beans and herbs. Each class is responsible for one part of the garden for a month. The vegetables are used in the school kitchen, and the students eat them at lunch. Last month they grew so many tomatoes that they sold some to families in the neighbourhood and used the money to buy new tools.\n\nThe science teacher, Mr Rojas, also uses the garden for his classes. \"It''s easier to understand how plants grow when you see it with your own eyes,\" he says.","svg":null,"table":null}'::jsonb, 'Why does Mr Rojas use the garden in his classes?', '[{"label":"A","text":"The head teacher told him to do it.","is_correct":false,"distractor_type":"Supone una orden que el texto no menciona.","explanation_feedback":"Incorrecta. La razón que él da es pedagógica, no una orden."},{"label":"B","text":"Students learn better by seeing plants grow.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Él dice que es más fácil entender cómo crecen las plantas viéndolo con los propios ojos."},{"label":"C","text":"The classroom is too small for his students.","is_correct":false,"distractor_type":"Inventa una razón práctica.","explanation_feedback":"Incorrecta. El texto no habla del tamaño del salón."},{"label":"D","text":"He wants to sell vegetables to families.","is_correct":false,"distractor_type":"Atribuye al profesor la venta de tomates.","explanation_feedback":"Incorrecta. Fueron los estudiantes quienes vendieron los tomates."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
