insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '5d6d83ea-05a5-5ef2-9be4-a0a655fc59db', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"An email from Bogotá","text":"Hi Tom,\nI''ve been in Bogotá for three weeks now and I''m really enjoying it. My host family is great. Doña Marta cooks amazing food, and her son Felipe is teaching me to play tejo. It''s a traditional game where you throw a heavy metal disc at a target. I''m terrible at it, but it''s a lot of fun!\n\nThe weather is not what I expected. I thought Colombia was always hot, but Bogotá is high in the mountains, so it''s often cold and it rains almost every afternoon. I had to buy a warm jacket in my first week.\n\nMy Spanish is getting better. At first I only understood a few words, but now I can have short conversations. My classes at the language school finish next month, and then I''m going to travel to the coast for a week before I go home.\n\nSee you soon,\nEmma","svg":null,"table":null}'::jsonb, 'Who is teaching Emma to play tejo?', '[{"label":"A","text":"Her friend Tom.","is_correct":false,"distractor_type":"Confunde al destinatario con un personaje del relato.","explanation_feedback":"Incorrecta. Tom es a quien le escribe el correo; no está en Bogotá."},{"label":"B","text":"Her host family''s son.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Felipe, el hijo de su familia anfitriona, le está enseñando."},{"label":"C","text":"Doña Marta, the mother.","is_correct":false,"distractor_type":"Confunde a los dos miembros de la familia.","explanation_feedback":"Incorrecta. Doña Marta cocina; quien enseña tejo es su hijo."},{"label":"D","text":"Her teacher at the school.","is_correct":false,"distractor_type":"Asocia «teaching» con la escuela de idiomas.","explanation_feedback":"Incorrecta. En la escuela estudia español; el tejo se lo enseña Felipe."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '6ffb8696-ddb7-536e-8f28-1316648b05eb', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"An email from Bogotá","text":"Hi Tom,\nI''ve been in Bogotá for three weeks now and I''m really enjoying it. My host family is great. Doña Marta cooks amazing food, and her son Felipe is teaching me to play tejo. It''s a traditional game where you throw a heavy metal disc at a target. I''m terrible at it, but it''s a lot of fun!\n\nThe weather is not what I expected. I thought Colombia was always hot, but Bogotá is high in the mountains, so it''s often cold and it rains almost every afternoon. I had to buy a warm jacket in my first week.\n\nMy Spanish is getting better. At first I only understood a few words, but now I can have short conversations. My classes at the language school finish next month, and then I''m going to travel to the coast for a week before I go home.\n\nSee you soon,\nEmma","svg":null,"table":null}'::jsonb, 'What does Emma say about tejo?', '[{"label":"A","text":"She is very good at it already.","is_correct":false,"distractor_type":"Lee al revés «I''m terrible at it».","explanation_feedback":"Incorrecta. Ella dice que juega muy mal."},{"label":"B","text":"She enjoys it although she plays badly.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice «I''m terrible at it, but it''s a lot of fun»."},{"label":"C","text":"She thinks it is too dangerous.","is_correct":false,"distractor_type":"Infiere peligro por el disco metálico.","explanation_feedback":"Incorrecta. Menciona que el disco es pesado, pero no dice que sea peligroso."},{"label":"D","text":"She played it before in her country.","is_correct":false,"distractor_type":"Agrega información que no está.","explanation_feedback":"Incorrecta. El texto sugiere que es nuevo para ella: Felipe se lo enseña."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
