select 'c10282c5-97ee-5624-bffe-67120368fa63', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"An email from Bogotá","text":"Hi Tom,\nI''ve been in Bogotá for three weeks now and I''m really enjoying it. My host family is great. Doña Marta cooks amazing food, and her son Felipe is teaching me to play tejo. It''s a traditional game where you throw a heavy metal disc at a target. I''m terrible at it, but it''s a lot of fun!\n\nThe weather is not what I expected. I thought Colombia was always hot, but Bogotá is high in the mountains, so it''s often cold and it rains almost every afternoon. I had to buy a warm jacket in my first week.\n\nMy Spanish is getting better. At first I only understood a few words, but now I can have short conversations. My classes at the language school finish next month, and then I''m going to travel to the coast for a week before I go home.\n\nSee you soon,\nEmma","svg":null,"table":null}'::jsonb, 'Why did Emma buy a jacket?', '[{"label":"A","text":"Doña Marta gave her the money for it.","is_correct":false,"distractor_type":"Inventa un dato.","explanation_feedback":"Incorrecta. El texto no dice quién pagó la chaqueta."},{"label":"B","text":"She is going to travel to the coast.","is_correct":false,"distractor_type":"Relaciona la compra con el viaje.","explanation_feedback":"Incorrecta. En la costa hace calor; la chaqueta es por el clima de Bogotá."},{"label":"C","text":"She wanted a souvenir from Colombia.","is_correct":false,"distractor_type":"Supone un motivo de turista.","explanation_feedback":"Incorrecta. La compró por el frío, no como recuerdo."},{"label":"D","text":"The weather in Bogotá was colder than she thought.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Pensaba que en Colombia siempre hacía calor, pero Bogotá es fría."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
