select '9b8978e7-80be-5007-a068-26162b360902', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"An email from Bogotá","text":"Hi Tom,\nI''ve been in Bogotá for three weeks now and I''m really enjoying it. My host family is great. Doña Marta cooks amazing food, and her son Felipe is teaching me to play tejo. It''s a traditional game where you throw a heavy metal disc at a target. I''m terrible at it, but it''s a lot of fun!\n\nThe weather is not what I expected. I thought Colombia was always hot, but Bogotá is high in the mountains, so it''s often cold and it rains almost every afternoon. I had to buy a warm jacket in my first week.\n\nMy Spanish is getting better. At first I only understood a few words, but now I can have short conversations. My classes at the language school finish next month, and then I''m going to travel to the coast for a week before I go home.\n\nSee you soon,\nEmma","svg":null,"table":null}'::jsonb, 'How has Emma''s Spanish changed?', '[{"label":"A","text":"She has stopped going to her classes.","is_correct":false,"distractor_type":"Confunde el futuro con el presente.","explanation_feedback":"Incorrecta. Las clases terminan el próximo mes; todavía asiste."},{"label":"B","text":"She speaks it perfectly now.","is_correct":false,"distractor_type":"Exagera el progreso.","explanation_feedback":"Incorrecta. Ella habla de conversaciones cortas, no de un dominio perfecto."},{"label":"C","text":"She can now have short conversations.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al comienzo entendía pocas palabras y ahora puede tener conversaciones cortas."},{"label":"D","text":"She still understands only a few words.","is_correct":false,"distractor_type":"Toma la situación inicial como la actual.","explanation_feedback":"Incorrecta. Eso era «at first»; ahora ha mejorado."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
