select 'a4b1ffae-de0c-5571-96a3-7e60bb0c006b', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"An email from Bogotá","text":"Hi Tom,\nI''ve been in Bogotá for three weeks now and I''m really enjoying it. My host family is great. Doña Marta cooks amazing food, and her son Felipe is teaching me to play tejo. It''s a traditional game where you throw a heavy metal disc at a target. I''m terrible at it, but it''s a lot of fun!\n\nThe weather is not what I expected. I thought Colombia was always hot, but Bogotá is high in the mountains, so it''s often cold and it rains almost every afternoon. I had to buy a warm jacket in my first week.\n\nMy Spanish is getting better. At first I only understood a few words, but now I can have short conversations. My classes at the language school finish next month, and then I''m going to travel to the coast for a week before I go home.\n\nSee you soon,\nEmma","svg":null,"table":null}'::jsonb, 'What will Emma do after her classes finish?', '[{"label":"A","text":"Start a new course in Bogotá.","is_correct":false,"distractor_type":"Inventa un plan.","explanation_feedback":"Incorrecta. No menciona otro curso."},{"label":"B","text":"Stay with her host family.","is_correct":false,"distractor_type":"Supone que se queda en Bogotá.","explanation_feedback":"Incorrecta. El plan es viajar a la costa."},{"label":"C","text":"Spend a week on the coast.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice que viajará a la costa una semana antes de volver a casa."},{"label":"D","text":"Go home immediately.","is_correct":false,"distractor_type":"Omite el viaje previo.","explanation_feedback":"Incorrecta. Antes de volver a casa piensa viajar una semana."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
