insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '5abbd928-9f4f-5809-8bcf-fb5bcd0747f8', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"A young chef","text":"Mariana Ortiz is only seventeen, but she already has her own cooking channel on the internet with more than fifty thousand followers. She started cooking when she was eight, helping her grandmother prepare arepas for the family''s small restaurant in Barranquilla.\n\nIn her videos, Mariana prepares traditional Colombian dishes, but she often changes the recipes to make them healthier. For example, she bakes her empanadas instead of frying them. \"I want young people to know that healthy food can also be delicious,\" she says.\n\nMariana records her videos on Sunday afternoons, when the restaurant is closed. Her younger brother holds the camera. She doesn''t earn much money from the channel yet, but she has received invitations to cook at food festivals. After finishing school, she hopes to study at a cooking school in Lima.","svg":null,"table":null}'::jsonb, 'How did Mariana learn to cook?', '[{"label":"A","text":"At a cooking school in Lima.","is_correct":false,"distractor_type":"Toma un plan futuro como pasado.","explanation_feedback":"Incorrecta. Estudiar en Lima es lo que espera hacer después del colegio."},{"label":"B","text":"At a food festival in Barranquilla.","is_correct":false,"distractor_type":"Mezcla datos del texto.","explanation_feedback":"Incorrecta. Los festivales son invitaciones recientes, no donde aprendió."},{"label":"C","text":"By helping her grandmother as a child.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Empezó a los ocho años ayudando a su abuela con las arepas."},{"label":"D","text":"By watching videos on the internet.","is_correct":false,"distractor_type":"Invierte la relación: ella hace videos.","explanation_feedback":"Incorrecta. Ella hace videos; no dice que aprendiera viéndolos."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
