select 'db47430a-4828-5fe3-9e99-25dc65e5c843', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"A young chef","text":"Mariana Ortiz is only seventeen, but she already has her own cooking channel on the internet with more than fifty thousand followers. She started cooking when she was eight, helping her grandmother prepare arepas for the family''s small restaurant in Barranquilla.\n\nIn her videos, Mariana prepares traditional Colombian dishes, but she often changes the recipes to make them healthier. For example, she bakes her empanadas instead of frying them. \"I want young people to know that healthy food can also be delicious,\" she says.\n\nMariana records her videos on Sunday afternoons, when the restaurant is closed. Her younger brother holds the camera. She doesn''t earn much money from the channel yet, but she has received invitations to cook at food festivals. After finishing school, she hopes to study at a cooking school in Lima.","svg":null,"table":null}'::jsonb, 'What is special about Mariana''s recipes?', '[{"label":"A","text":"She fries everything to make it tasty.","is_correct":false,"distractor_type":"Lee al revés el ejemplo de las empanadas.","explanation_feedback":"Incorrecta. Ella hornea las empanadas en vez de freírlas."},{"label":"B","text":"She uses her grandmother''s recipes exactly.","is_correct":false,"distractor_type":"Ignora que cambia las recetas.","explanation_feedback":"Incorrecta. El texto dice que a menudo modifica las recetas."},{"label":"C","text":"She only cooks food from other countries.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Ella prepara platos tradicionales colombianos."},{"label":"D","text":"She makes traditional dishes healthier.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cambia las recetas tradicionales para hacerlas más saludables, como hornear empanadas."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
