select '0b7a8d04-19d7-5c52-9b92-5ecac4c61df8', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"A young chef","text":"Mariana Ortiz is only seventeen, but she already has her own cooking channel on the internet with more than fifty thousand followers. She started cooking when she was eight, helping her grandmother prepare arepas for the family''s small restaurant in Barranquilla.\n\nIn her videos, Mariana prepares traditional Colombian dishes, but she often changes the recipes to make them healthier. For example, she bakes her empanadas instead of frying them. \"I want young people to know that healthy food can also be delicious,\" she says.\n\nMariana records her videos on Sunday afternoons, when the restaurant is closed. Her younger brother holds the camera. She doesn''t earn much money from the channel yet, but she has received invitations to cook at food festivals. After finishing school, she hopes to study at a cooking school in Lima.","svg":null,"table":null}'::jsonb, 'Why does Mariana record on Sunday afternoons?', '[{"label":"A","text":"The light is better in the afternoon.","is_correct":false,"distractor_type":"Supone una razón técnica.","explanation_feedback":"Incorrecta. El texto no menciona la luz."},{"label":"B","text":"The restaurant is closed then.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Graba los domingos en la tarde porque el restaurante está cerrado."},{"label":"C","text":"Her followers watch more on Sundays.","is_correct":false,"distractor_type":"Inventa una razón sobre la audiencia.","explanation_feedback":"Incorrecta. El texto no habla de cuándo ven los videos sus seguidores."},{"label":"D","text":"Her brother has no school then.","is_correct":false,"distractor_type":"Supone una razón relacionada con el hermano.","explanation_feedback":"Incorrecta. El hermano sostiene la cámara, pero la razón dada es el cierre del restaurante."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
