select 'cecaac78-f1e5-5f1c-9d18-a10fd0bca4e2', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"A young chef","text":"Mariana Ortiz is only seventeen, but she already has her own cooking channel on the internet with more than fifty thousand followers. She started cooking when she was eight, helping her grandmother prepare arepas for the family''s small restaurant in Barranquilla.\n\nIn her videos, Mariana prepares traditional Colombian dishes, but she often changes the recipes to make them healthier. For example, she bakes her empanadas instead of frying them. \"I want young people to know that healthy food can also be delicious,\" she says.\n\nMariana records her videos on Sunday afternoons, when the restaurant is closed. Her younger brother holds the camera. She doesn''t earn much money from the channel yet, but she has received invitations to cook at food festivals. After finishing school, she hopes to study at a cooking school in Lima.","svg":null,"table":null}'::jsonb, 'What does the text say about money?', '[{"label":"A","text":"She pays her brother to hold the camera.","is_correct":false,"distractor_type":"Inventa una relación laboral.","explanation_feedback":"Incorrecta. No dice que le pague a su hermano."},{"label":"B","text":"She doesn''t make much from her channel yet.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice «She doesn''t earn much money from the channel yet»."},{"label":"C","text":"She is rich because of her followers.","is_correct":false,"distractor_type":"Asocia muchos seguidores con mucho dinero.","explanation_feedback":"Incorrecta. El texto dice lo contrario: aún no gana mucho."},{"label":"D","text":"She uses the money to help the restaurant.","is_correct":false,"distractor_type":"Inventa un uso del dinero.","explanation_feedback":"Incorrecta. El texto no dice que dé dinero al restaurante."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
