select '73465ca1-dfb7-5813-a948-00c8a01be8c1', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"A young chef","text":"Mariana Ortiz is only seventeen, but she already has her own cooking channel on the internet with more than fifty thousand followers. She started cooking when she was eight, helping her grandmother prepare arepas for the family''s small restaurant in Barranquilla.\n\nIn her videos, Mariana prepares traditional Colombian dishes, but she often changes the recipes to make them healthier. For example, she bakes her empanadas instead of frying them. \"I want young people to know that healthy food can also be delicious,\" she says.\n\nMariana records her videos on Sunday afternoons, when the restaurant is closed. Her younger brother holds the camera. She doesn''t earn much money from the channel yet, but she has received invitations to cook at food festivals. After finishing school, she hopes to study at a cooking school in Lima.","svg":null,"table":null}'::jsonb, 'What does Mariana want young people to understand?', '[{"label":"A","text":"Everyone should study in Lima.","is_correct":false,"distractor_type":"Generaliza su plan personal.","explanation_feedback":"Incorrecta. Estudiar en Lima es su plan, no un consejo."},{"label":"B","text":"Fried food is the most delicious.","is_correct":false,"distractor_type":"Contradice su mensaje.","explanation_feedback":"Incorrecta. Ella prefiere hornear para que sea más saludable."},{"label":"C","text":"Healthy food can taste good too.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella dice que quiere que los jóvenes sepan que la comida saludable también puede ser deliciosa."},{"label":"D","text":"Cooking is a good way to earn money.","is_correct":false,"distractor_type":"Se enfoca en el dinero, tema secundario.","explanation_feedback":"Incorrecta. Su mensaje es sobre comida saludable, no sobre ganar dinero."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
