insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7bb2ac87-569e-5b1b-8528-87ac1ba45a57', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"My trip to the Tatacoa Desert","text":"Last December, my family and I spent three days in the Tatacoa Desert, in Huila. I was surprised because I didn''t know Colombia had a desert. It isn''t a desert of sand like in films. The ground is red and grey, and there are many cactus plants.\n\nDuring the day it was very hot, so we stayed in our cabin and only went out early in the morning and late in the afternoon. My favourite part was the night. Because there are no big cities near the desert, the sky is very dark and you can see thousands of stars. We visited a small observatory where a guide showed us Saturn through a telescope. I could see its rings!\n\nIf you go, take a hat, a lot of water and sun cream. And don''t forget a jacket: the nights can be cooler than you think.","svg":null,"table":null}'::jsonb, 'Why was the writer surprised?', '[{"label":"A","text":"It rained every day of the trip.","is_correct":false,"distractor_type":"Inventa un dato del clima.","explanation_feedback":"Incorrecta. El texto dice que hacía mucho calor de día."},{"label":"B","text":"There were no plants in the desert.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Menciona muchos cactus."},{"label":"C","text":"The desert was full of sand.","is_correct":false,"distractor_type":"Contradice la descripción.","explanation_feedback":"Incorrecta. El texto dice que no es un desierto de arena."},{"label":"D","text":"The writer didn''t know Colombia had a desert.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice «I didn''t know Colombia had a desert»."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '2262f2b0-fba0-5fce-9056-12ff14e84500', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"My trip to the Tatacoa Desert","text":"Last December, my family and I spent three days in the Tatacoa Desert, in Huila. I was surprised because I didn''t know Colombia had a desert. It isn''t a desert of sand like in films. The ground is red and grey, and there are many cactus plants.\n\nDuring the day it was very hot, so we stayed in our cabin and only went out early in the morning and late in the afternoon. My favourite part was the night. Because there are no big cities near the desert, the sky is very dark and you can see thousands of stars. We visited a small observatory where a guide showed us Saturn through a telescope. I could see its rings!\n\nIf you go, take a hat, a lot of water and sun cream. And don''t forget a jacket: the nights can be cooler than you think.","svg":null,"table":null}'::jsonb, 'Why did the family stay in the cabin during the day?', '[{"label":"A","text":"The guide told them to stay inside.","is_correct":false,"distractor_type":"Inventa una indicación.","explanation_feedback":"Incorrecta. El guía aparece en el observatorio, de noche."},{"label":"B","text":"It was too dark to see anything.","is_correct":false,"distractor_type":"Confunde el día con la noche.","explanation_feedback":"Incorrecta. La oscuridad era de noche, no de día."},{"label":"C","text":"It was too hot outside.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hacía mucho calor de día, así que solo salían temprano o tarde."},{"label":"D","text":"They were tired after the trip.","is_correct":false,"distractor_type":"Supone una razón no mencionada.","explanation_feedback":"Incorrecta. La razón dada es el calor."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
