insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '4f71643d-7417-5576-8093-a353a993d279', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"My trip to the Tatacoa Desert","text":"Last December, my family and I spent three days in the Tatacoa Desert, in Huila. I was surprised because I didn''t know Colombia had a desert. It isn''t a desert of sand like in films. The ground is red and grey, and there are many cactus plants.\n\nDuring the day it was very hot, so we stayed in our cabin and only went out early in the morning and late in the afternoon. My favourite part was the night. Because there are no big cities near the desert, the sky is very dark and you can see thousands of stars. We visited a small observatory where a guide showed us Saturn through a telescope. I could see its rings!\n\nIf you go, take a hat, a lot of water and sun cream. And don''t forget a jacket: the nights can be cooler than you think.","svg":null,"table":null}'::jsonb, 'Why can you see so many stars in the Tatacoa?', '[{"label":"A","text":"The guide gives everyone a telescope.","is_correct":false,"distractor_type":"Generaliza el telescopio del observatorio.","explanation_feedback":"Incorrecta. Solo usaron un telescopio en el observatorio; las estrellas se ven a simple vista."},{"label":"B","text":"The desert is very high in the mountains.","is_correct":false,"distractor_type":"Supone una razón geográfica no mencionada.","explanation_feedback":"Incorrecta. El texto explica la oscuridad por la ausencia de ciudades."},{"label":"C","text":"There are no large cities near it.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin ciudades grandes cerca, el cielo es muy oscuro."},{"label":"D","text":"It is very hot during the night.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Las noches pueden ser frescas, y el calor no explica las estrellas."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
