select '8b9dc60e-fcb7-58c5-bb0b-73c0f367cc47', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"My trip to the Tatacoa Desert","text":"Last December, my family and I spent three days in the Tatacoa Desert, in Huila. I was surprised because I didn''t know Colombia had a desert. It isn''t a desert of sand like in films. The ground is red and grey, and there are many cactus plants.\n\nDuring the day it was very hot, so we stayed in our cabin and only went out early in the morning and late in the afternoon. My favourite part was the night. Because there are no big cities near the desert, the sky is very dark and you can see thousands of stars. We visited a small observatory where a guide showed us Saturn through a telescope. I could see its rings!\n\nIf you go, take a hat, a lot of water and sun cream. And don''t forget a jacket: the nights can be cooler than you think.","svg":null,"table":null}'::jsonb, 'What was the writer''s favourite part of the trip?', '[{"label":"A","text":"The cabin.","is_correct":false,"distractor_type":"Elige un lugar donde pasaban el calor.","explanation_feedback":"Incorrecta. La cabaña era para protegerse del calor."},{"label":"B","text":"The cactus plants.","is_correct":false,"distractor_type":"Elige un detalle descriptivo.","explanation_feedback":"Incorrecta. Menciona los cactus, pero no como lo favorito."},{"label":"C","text":"The red ground.","is_correct":false,"distractor_type":"Elige un detalle del paisaje.","explanation_feedback":"Incorrecta. Describe el suelo, pero lo favorito fue la noche."},{"label":"D","text":"The night sky.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice «My favourite part was the night» y describe las estrellas."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
