insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '27b6763b-4ddb-5bdf-be02-dc308a66f3ea', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"My trip to the Tatacoa Desert","text":"Last December, my family and I spent three days in the Tatacoa Desert, in Huila. I was surprised because I didn''t know Colombia had a desert. It isn''t a desert of sand like in films. The ground is red and grey, and there are many cactus plants.\n\nDuring the day it was very hot, so we stayed in our cabin and only went out early in the morning and late in the afternoon. My favourite part was the night. Because there are no big cities near the desert, the sky is very dark and you can see thousands of stars. We visited a small observatory where a guide showed us Saturn through a telescope. I could see its rings!\n\nIf you go, take a hat, a lot of water and sun cream. And don''t forget a jacket: the nights can be cooler than you think.","svg":null,"table":null}'::jsonb, 'What advice does the writer give at the end?', '[{"label":"A","text":"Don''t go out at night because it''s cold.","is_correct":false,"distractor_type":"Contradice su recomendación.","explanation_feedback":"Incorrecta. La noche fue su parte favorita; solo pide llevar chaqueta."},{"label":"B","text":"Buy a telescope before you go.","is_correct":false,"distractor_type":"Generaliza el uso del telescopio.","explanation_feedback":"Incorrecta. Usaron el telescopio del observatorio; no aconseja comprarlo."},{"label":"C","text":"Bring things for both heat and cool nights.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Aconseja sombrero, agua y bloqueador, y también una chaqueta para las noches."},{"label":"D","text":"Visit the desert only in December.","is_correct":false,"distractor_type":"Generaliza la fecha del viaje.","explanation_feedback":"Incorrecta. Viajaron en diciembre, pero no lo recomienda como única fecha."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '835ea58e-99e6-5537-8ea4-307937553ca6', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Phones at the dinner table","text":"In many homes, families eat dinner while they look at their phones. A school in Cali wanted to know how this affects family life, so it asked 300 students to answer some questions.\n\nMore than half of the students said they use their phones during meals. Many of them said their parents do the same. But when the school asked them to try one week without phones at dinner, the results were interesting. Most students said they talked more with their families and learned things they didn''t know about their parents. Some said the first two days were difficult and a bit boring.\n\nAfter the experiment, 60% of the families decided to keep a \"no phones\" rule at least three days a week. \"Now my dad tells us stories about when he was young,\" said one student.","svg":null,"table":null}'::jsonb, 'Why did the school ask students questions?', '[{"label":"A","text":"To choose the best phone for students.","is_correct":false,"distractor_type":"Inventa un propósito comercial.","explanation_feedback":"Incorrecta. El estudio no compara celulares."},{"label":"B","text":"To learn how phones at meals affect families.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La escuela quería saber cómo afecta a la vida familiar usar el celular en la cena."},{"label":"C","text":"To find out what students eat at home.","is_correct":false,"distractor_type":"Se queda con «dinner».","explanation_feedback":"Incorrecta. La comida no es el tema; lo es el uso del celular."},{"label":"D","text":"To ban phones in the school.","is_correct":false,"distractor_type":"Supone una medida escolar.","explanation_feedback":"Incorrecta. El experimento fue en casa, durante la cena."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
