select 'd6a57fa8-380f-5068-b247-32cf4dd41c4e', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Phones at the dinner table","text":"In many homes, families eat dinner while they look at their phones. A school in Cali wanted to know how this affects family life, so it asked 300 students to answer some questions.\n\nMore than half of the students said they use their phones during meals. Many of them said their parents do the same. But when the school asked them to try one week without phones at dinner, the results were interesting. Most students said they talked more with their families and learned things they didn''t know about their parents. Some said the first two days were difficult and a bit boring.\n\nAfter the experiment, 60% of the families decided to keep a \"no phones\" rule at least three days a week. \"Now my dad tells us stories about when he was young,\" said one student.","svg":null,"table":null}'::jsonb, 'What did more than half of the students say?', '[{"label":"A","text":"They use their phones while they eat.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Más de la mitad dijo que usa el celular durante las comidas."},{"label":"B","text":"Their parents never use phones.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Muchos dijeron que sus padres hacen lo mismo."},{"label":"C","text":"They always eat alone.","is_correct":false,"distractor_type":"Inventa un dato.","explanation_feedback":"Incorrecta. El texto habla de comidas en familia."},{"label":"D","text":"They don''t have their own phones.","is_correct":false,"distractor_type":"Inventa un dato.","explanation_feedback":"Incorrecta. El texto no habla de quién tiene celular."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
