select 'e03beaa8-5931-5be9-9f3f-f60b9bd173eb', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Phones at the dinner table","text":"In many homes, families eat dinner while they look at their phones. A school in Cali wanted to know how this affects family life, so it asked 300 students to answer some questions.\n\nMore than half of the students said they use their phones during meals. Many of them said their parents do the same. But when the school asked them to try one week without phones at dinner, the results were interesting. Most students said they talked more with their families and learned things they didn''t know about their parents. Some said the first two days were difficult and a bit boring.\n\nAfter the experiment, 60% of the families decided to keep a \"no phones\" rule at least three days a week. \"Now my dad tells us stories about when he was young,\" said one student.","svg":null,"table":null}'::jsonb, 'What happened during the week without phones?', '[{"label":"A","text":"Most students talked more with their families.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La mayoría dijo que habló más con su familia y aprendió cosas de sus padres."},{"label":"B","text":"Families stopped eating dinner together.","is_correct":false,"distractor_type":"Contradice el resultado.","explanation_feedback":"Incorrecta. Siguieron cenando juntos y conversaron más."},{"label":"C","text":"Parents used their phones even more.","is_correct":false,"distractor_type":"Inventa un resultado.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"D","text":"All students found it boring all week.","is_correct":false,"distractor_type":"Generaliza lo que dijeron algunos sobre dos días.","explanation_feedback":"Incorrecta. Solo algunos dijeron que los dos primeros días fueron difíciles."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
