select '969a35b7-d979-5e59-8753-93e0b2b2c0c8', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Phones at the dinner table","text":"In many homes, families eat dinner while they look at their phones. A school in Cali wanted to know how this affects family life, so it asked 300 students to answer some questions.\n\nMore than half of the students said they use their phones during meals. Many of them said their parents do the same. But when the school asked them to try one week without phones at dinner, the results were interesting. Most students said they talked more with their families and learned things they didn''t know about their parents. Some said the first two days were difficult and a bit boring.\n\nAfter the experiment, 60% of the families decided to keep a \"no phones\" rule at least three days a week. \"Now my dad tells us stories about when he was young,\" said one student.","svg":null,"table":null}'::jsonb, 'What does "the first two days were difficult" tell us?', '[{"label":"A","text":"Changing the habit was hard at the start.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Indica que al principio costó dejar el celular, aunque luego mejoró."},{"label":"B","text":"The students didn''t finish the experiment.","is_correct":false,"distractor_type":"Infiere un abandono no mencionado.","explanation_feedback":"Incorrecta. El texto no dice que lo dejaran."},{"label":"C","text":"The food was bad on those days.","is_correct":false,"distractor_type":"Relaciona «difficult» con la comida.","explanation_feedback":"Incorrecta. La dificultad era no usar el celular."},{"label":"D","text":"The experiment lasted only two days.","is_correct":false,"distractor_type":"Confunde el comienzo con la duración.","explanation_feedback":"Incorrecta. El experimento duró una semana."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
