select '5a9d954f-63ef-559c-b355-fe13dc25061e', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Phones at the dinner table","text":"In many homes, families eat dinner while they look at their phones. A school in Cali wanted to know how this affects family life, so it asked 300 students to answer some questions.\n\nMore than half of the students said they use their phones during meals. Many of them said their parents do the same. But when the school asked them to try one week without phones at dinner, the results were interesting. Most students said they talked more with their families and learned things they didn''t know about their parents. Some said the first two days were difficult and a bit boring.\n\nAfter the experiment, 60% of the families decided to keep a \"no phones\" rule at least three days a week. \"Now my dad tells us stories about when he was young,\" said one student.","svg":null,"table":null}'::jsonb, 'What did 60% of the families decide?', '[{"label":"A","text":"To have meals without phones on some days.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Decidieron mantener la regla «no phones» al menos tres días por semana."},{"label":"B","text":"To repeat the questions every year.","is_correct":false,"distractor_type":"Inventa una decisión de la escuela.","explanation_feedback":"Incorrecta. La decisión fue de las familias sobre su rutina."},{"label":"C","text":"To never use phones at home again.","is_correct":false,"distractor_type":"Exagera la decisión.","explanation_feedback":"Incorrecta. La regla es para la cena y al menos tres días por semana, no siempre."},{"label":"D","text":"To buy new phones for their children.","is_correct":false,"distractor_type":"Inventa una decisión.","explanation_feedback":"Incorrecta. No se menciona comprar celulares."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
