insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '4409e8c0-210d-5db8-87f1-cb43a32fe48d', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Reading Club","text":"THE PUBLIC LIBRARY READING CLUB IS BACK!\n\nAre you between 13 and 17 years old? Do you love stories, or do you want to start reading more? Join our free reading club this holiday.\n\nWe meet every Wednesday from 3 to 5 p.m. in Room 2, on the first floor. Each week we read a short story or a chapter of a novel and then talk about it. You don''t need to buy any books: the library gives you a copy, and you can take it home.\n\nAt the end of the holidays, members will write their own short story. The best three stories will be printed in the library''s magazine.\n\nTo join, come to the information desk with a parent or guardian before 15 June. Places are limited to 20 people.","svg":null,"table":null}'::jsonb, 'Who can join the reading club?', '[{"label":"A","text":"Anyone who works at the library.","is_correct":false,"distractor_type":"Inventa un requisito.","explanation_feedback":"Incorrecta. El club es para jóvenes de 13 a 17 años."},{"label":"B","text":"Teenagers from 13 to 17.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El aviso es para jóvenes entre 13 y 17 años."},{"label":"C","text":"Only students who read a lot.","is_correct":false,"distractor_type":"Ignora que también invita a quienes quieren empezar.","explanation_feedback":"Incorrecta. El aviso invita también a quienes quieren empezar a leer."},{"label":"D","text":"Parents and their children.","is_correct":false,"distractor_type":"Confunde el requisito de inscripción con los miembros.","explanation_feedback":"Incorrecta. El acudiente acompaña la inscripción, pero el club es para jóvenes."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
from public.evidences e where e.code = 'IN.E5'
on conflict (id) do nothing;
