select 'b3907e94-6b48-5bb8-ad78-6f61aecee874', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Reading Club","text":"THE PUBLIC LIBRARY READING CLUB IS BACK!\n\nAre you between 13 and 17 years old? Do you love stories, or do you want to start reading more? Join our free reading club this holiday.\n\nWe meet every Wednesday from 3 to 5 p.m. in Room 2, on the first floor. Each week we read a short story or a chapter of a novel and then talk about it. You don''t need to buy any books: the library gives you a copy, and you can take it home.\n\nAt the end of the holidays, members will write their own short story. The best three stories will be printed in the library''s magazine.\n\nTo join, come to the information desk with a parent or guardian before 15 June. Places are limited to 20 people.","svg":null,"table":null}'::jsonb, 'What happens at each meeting?', '[{"label":"A","text":"Members read something and discuss it.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Cada semana leen un cuento o un capítulo y luego conversan."},{"label":"B","text":"Members buy a new novel.","is_correct":false,"distractor_type":"Contradice el aviso.","explanation_feedback":"Incorrecta. No hace falta comprar libros."},{"label":"C","text":"Members write a story every week.","is_correct":false,"distractor_type":"Generaliza la actividad final.","explanation_feedback":"Incorrecta. Escribir el cuento es al final de las vacaciones."},{"label":"D","text":"Members print the library magazine.","is_correct":false,"distractor_type":"Confunde la revista con la reunión.","explanation_feedback":"Incorrecta. La revista publicará los mejores cuentos al final."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
