select '6ca4462b-7169-5c44-b338-d318ca5fa67b', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Reading Club","text":"THE PUBLIC LIBRARY READING CLUB IS BACK!\n\nAre you between 13 and 17 years old? Do you love stories, or do you want to start reading more? Join our free reading club this holiday.\n\nWe meet every Wednesday from 3 to 5 p.m. in Room 2, on the first floor. Each week we read a short story or a chapter of a novel and then talk about it. You don''t need to buy any books: the library gives you a copy, and you can take it home.\n\nAt the end of the holidays, members will write their own short story. The best three stories will be printed in the library''s magazine.\n\nTo join, come to the information desk with a parent or guardian before 15 June. Places are limited to 20 people.","svg":null,"table":null}'::jsonb, 'What does the library give members?', '[{"label":"A","text":"Lunch after each meeting.","is_correct":false,"distractor_type":"Inventa un beneficio.","explanation_feedback":"Incorrecta. El aviso no menciona comida."},{"label":"B","text":"A free magazine every week.","is_correct":false,"distractor_type":"Confunde la revista con un obsequio semanal.","explanation_feedback":"Incorrecta. La revista publica los mejores cuentos al final."},{"label":"C","text":"Money to buy books.","is_correct":false,"distractor_type":"Inventa un beneficio.","explanation_feedback":"Incorrecta. No hay dinero; entregan copias."},{"label":"D","text":"A copy of what they are going to read.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La biblioteca entrega una copia que pueden llevar a casa."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
