select 'bfd141f5-dc64-5fe8-b639-e59ab9b3f2d2', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Reading Club","text":"THE PUBLIC LIBRARY READING CLUB IS BACK!\n\nAre you between 13 and 17 years old? Do you love stories, or do you want to start reading more? Join our free reading club this holiday.\n\nWe meet every Wednesday from 3 to 5 p.m. in Room 2, on the first floor. Each week we read a short story or a chapter of a novel and then talk about it. You don''t need to buy any books: the library gives you a copy, and you can take it home.\n\nAt the end of the holidays, members will write their own short story. The best three stories will be printed in the library''s magazine.\n\nTo join, come to the information desk with a parent or guardian before 15 June. Places are limited to 20 people.","svg":null,"table":null}'::jsonb, 'What will happen to the best three stories?', '[{"label":"A","text":"They will be sold at the desk.","is_correct":false,"distractor_type":"Relaciona el mostrador con ventas.","explanation_feedback":"Incorrecta. El mostrador es para inscribirse."},{"label":"B","text":"They will appear in the library''s magazine.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los tres mejores cuentos se imprimirán en la revista de la biblioteca."},{"label":"C","text":"They will win a trip.","is_correct":false,"distractor_type":"Inventa un premio.","explanation_feedback":"Incorrecta. No se menciona ningún viaje."},{"label":"D","text":"They will be read on the radio.","is_correct":false,"distractor_type":"Inventa un premio.","explanation_feedback":"Incorrecta. El aviso habla de la revista, no de radio."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
