select '4f55d021-3fdb-5214-849b-c5d9d0c5b285', e.id, 'IN', (select id from public.content_components where code = 'IN.P5'), 'qa_passed', 'cefr_part', '{"title":"Reading Club","text":"THE PUBLIC LIBRARY READING CLUB IS BACK!\n\nAre you between 13 and 17 years old? Do you love stories, or do you want to start reading more? Join our free reading club this holiday.\n\nWe meet every Wednesday from 3 to 5 p.m. in Room 2, on the first floor. Each week we read a short story or a chapter of a novel and then talk about it. You don''t need to buy any books: the library gives you a copy, and you can take it home.\n\nAt the end of the holidays, members will write their own short story. The best three stories will be printed in the library''s magazine.\n\nTo join, come to the information desk with a parent or guardian before 15 June. Places are limited to 20 people.","svg":null,"table":null}'::jsonb, 'What must you do to join?', '[{"label":"A","text":"Write a short story first.","is_correct":false,"distractor_type":"Toma la actividad final como requisito.","explanation_feedback":"Incorrecta. El cuento se escribe al final, no para entrar."},{"label":"B","text":"Go to the desk with an adult before 15 June.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hay que ir al mostrador con un padre o acudiente antes del 15 de junio."},{"label":"C","text":"Pay at the information desk.","is_correct":false,"distractor_type":"Contradice «free».","explanation_feedback":"Incorrecta. El club es gratuito."},{"label":"D","text":"Send an email to Room 2.","is_correct":false,"distractor_type":"Inventa un medio de inscripción.","explanation_feedback":"Incorrecta. La inscripción es presencial en el mostrador."}]'::jsonb, 'A2', 1.1, 0, 0.25, 70, 'original_generated'
